      "id": "T16",
      "kind": "open_question",
      "summary": "Whether Outlook calendar synchronization for bookings should be included in the first release or excluded.",
      "citations": [
        {
          "block_id": "U1",
          "quote": "The reviewer has not answered this yet: Should Outlook calendar synchronization for bookings be included in the first release or is it excluded?"
        }
      ]
    },
