      "title": "Facilities Administration and Booking Control",
      "description": "Provides the Facilities Office with comprehensive oversight and control over room bookings and maintenance. It ensures administrators can track who booked each room and manage facility availability effectively.",
      "criteria": [
        {
          "text": "When Facilities staff view room bookings, they can see the identity of the person who booked each room.",
          "origin": "source",
