      "description": "As a user, I want to search rooms by date, time and capacity, and book an individual one-off slot, so that I can secure a study space.\n\nUsers need to find and reserve rooms for single study sessions without creating recurring reservations.",
      "criteria": [
        {
          "text": "When a user specifies date, time, and capacity criteria, the system returns matching available rooms.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- A user can search rooms by date, time and capacity, and book an individual one-off slot."
            }
          ]
        },
        {
          "text": "When a user selects an available room slot, the booking is successfully confirmed.",
          "origin": "proposed",
          "citations": []
        },
        {
          "text": "When a user requests a booking duration of up to three hours, the booking is accepted.",
          "origin": "source",
          "citations": [
            {
              "block_id": "A1",
              "quote": "Three hours is the maximum. The brief is out of date on this point."
            }
          ]
        },
        {
          "text": "When a user requests a booking duration exceeding three hours, the booking is refused.",
          "origin": "source",
          "citations": [
            {
              "block_id": "A1",
              "quote": "Three hours is the maximum. The brief is out of date on this point."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T5",
        "T14"
      ]
    },
