      "ref": "S3",
      "kind": "story",
      "parent_ref": "E1",
      "title": "Prevent Double Bookings",
      "description": "As a user, I want the system to reject overlapping bookings, so that double bookings are eliminated.\n\nOverlapping requests for the same room at the same time must be prevented to ensure reliable scheduling.",
      "criteria": [
        {
          "text": "When a user attempts to book a room that has already been booked for that time, the booking service rejects the overlapping booking.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B15",
              "quote": "Priya: The booking service will reject an overlapping booking for the same room. That part is straightforward."
            }
          ]
        },
        {
          "text": "When an overlapping booking is rejected, the user is informed that the slot is unavailable.",
          "origin": "proposed",
          "citations": []
        }
      ],
      "assumptions": [],
